window.DOSIK=window.DOSIK||{};DOSIK["fm_system"]={"2":[{"t":"tree","title":"옥내소화전설비의 설치 기준","root":"옥내소화전설비","branches":[["송수구","송수 및 그 밖의 소화작업에 지장을 주지 않도록 설치할 것 · 송수구로부터 주배관에 이르는 연결배관에는 개폐밸브를 설치하지 않을 것 · 지면으로부터 높이가 0.5미터 이상 1미터 이하의 위치에 설치할 것"],["감시제어반","다른 부분과 방화구획을 할 것 · 피난층 또는 지하 1층에 설치할 것 · 바닥면적은 감시제어반의 설치에 필요한 면적 외에 화재 시 소방대원이 그 감시제어반의 조작에 필요한 최소면적 이상으로 할 것"],["펌프","펌프는 전용으로 할 것(다만, 다른 소화설비와 겸용하는 경우 각각의 소화설비의 성능에 지장이 없을 때에는 그렇지 않음) · 펌프축은 스테인리스 등 부식에 강한 재질을 사용할 것"],["동결 방지","동결방지조치를 하거나 동결의 우려가 없는 장소에 설치할 것"],["배관","펌프의 흡입 측 배관은 공기 고임이 생기지 아니하는 구조로 하고 여과장치를 설치하여야 한다 · 펌프의 토출 측 주배관의 구경은 유속이 4 m/s 이하가 될 수 있는 크기 이상으로 하여야 한다"]]},{"t":"def","term":"연결송수관설비의 배관과 겸용할 경우","text":"주배관은 구경 100 mm 이상, 방수구로 연결되는 배관의 구경은 65 mm 이상인 것으로 하여야 한다"}],"3":[{"t":"tree","title":"옥외소화전설비의 설치 기준","root":"옥외소화전설비","branches":[["수평거리","특정소방대상물의 각 부분으로부터 하나의 옥외소화전까지의 수평거리가 40 m 이하가 되도록 할 것"],["방수총","공장 또는 창고시설로서 750배 이상의 특수가연물을 저장ㆍ취급하는 경우에는 각 옥외소화전 5 m 이내에 방수총을 별도로 설치하거나 옥외소화전과 방수총이 겸용으로 된 것으로 설치할 것"],["호스접결구","옥외소화전의 호스접결구가 지면으로부터 0.5 m 이상 1 m 이하의 높이에 위치하도록 설치할 것"],["배관","배관과 배관이음쇠는 배관용 스테인리스 강관(KS D 3576)의 이음을 용접으로 할 경우 텅스텐 불활성 가스 아크 용접방식에 따른다"]]}],"4":[{"t":"table","title":"스프링클러헤드의 설치 기준","head":["항목","기준"],"rows":[["차폐판","상부에 설치된 헤드의 방출수에 따라 감열부에 영향을 받을 우려가 있는 헤드에는 방출수를 차단할 수 있는 유효한 차폐판을 설치할 것"],["벽과 헤드 간 공간","살수가 방해되지 아니하도록 벽과 스프링클러헤드간의 공간은 10 cm 이상으로 한다"]]}],"5":[{"t":"tree","title":"물분무소화설비·미분무소화설비의 기준","root":"물분무·미분무소화설비","branches":[["필터·스트레이너","사용되는 필터 또는 스트레이너의 메쉬는 헤드 오리피스 지름의 80% 이하가 되어야 한다"],["구성요소","설비에 사용되는 구성요소는 STS 304 이상의 재료를 사용하여야 한다"],["가압송수장치","가압송수장치가 기동되는 경우에는 자동으로 정지되지 아니하도록 하여야 한다"]]}],"6":[{"t":"table","title":"포소화설비의 용어","head":["용어","뜻"],"rows":[["비확관형 분기배관","배관의 측면에 분기호칭내경 이상의 구멍을 뚫고 배관이음쇠를 용접 이음한 배관"],["포소화전설비","포소화전방수구·호스 및 이동식포노즐을 사용하는 설비"],["주펌프","구동장치의 회전 또는 왕복운동으로 소화용수를 가압하여 그 압력으로 급수하는 주된 펌프"]]},{"t":"tree","title":"호스릴함과 방수구","root":"호스릴포·포소화전","branches":[["호스릴함 높이","호스릴함 또는 호스함은 바닥으로부터 높이 1.5 m 이하의 위치에 설치하고 그 표면에는 “포호스릴함(또는 포소화전함)”이라고 표시한 표지와 적색의 위치표시등을 설치할 것"],["호스릴함 위치","호스릴 또는 호스를 호스릴포방수구 또는 포소화전방수구로 분리하여 비치하는 때에는 그로부터 3 m 이내의 거리에 호스릴함 또는 호스함을 설치할 것"],["수평거리","방호대상물의 각 부분으로부터 하나의 호스릴포방수구까지의 수평거리는 15 m 이하(포소화전방수구의 경우에는 25 m 이하)가 되도록 하고 호스릴 또는 호스의 길이는 방호대상물의 각 부분에 포가 유효하게 뿌려질 수 있도록 할 것"]]}],"7":[{"t":"tree","title":"설치 위치","root":"이산화탄소소화설비","branches":[["저장용기실","소화약제 저장용기실 내의 소화배관에 설치해야 한다"],["점검·관리","점검 및 관리가 쉬운 위치에 설치해야 한다"],["방호구역별","방호구역별로 선택밸브 직후 2차측 배관에 설치해야 한다"]]},{"t":"tree","title":"저장용기와 분사헤드","root":"이산화탄소소화설비","branches":[["저장용기","소화약제 저장용기는 온도가 40℃ 이하이고, 온도변화가 작은 곳에 설치하여야 한다"],["분사헤드 설치 제한","사람이 상시 근무하거나 다수인이 출입·통행하는 곳과 자기연소성물질 또는 활성금속물질 등을 저장하는 장소에는 설치해서는 안 된다"]]}],"8":[{"t":"table","title":"할론소화설비의 기동용가스용기","head":["항목","기준"],"rows":[["용기와 밸브","기동용가스용기 및 해당 용기에 사용하는 밸브는 25 MPa 이상의 압력에 견딜 수 있는 것으로 설치해야 한다"],["가스압력식 기동장치","기동용가스용기의 용적은 1ℓ 이상으로 하고, 해당 용기에 저장하는 이산화탄소의 양은 0.6 kg 이상으로 하며, 충전비는 1.5 이상으로 할 것"]]}],"10":[{"t":"tree","title":"분말소화설비의 설치 기준","root":"분말소화설비","branches":[["설치 장소","방호구역 외의 장소에 설치할 것. 다만, 방호구역 내에 설치할 경우에는 피난 및 조작이 용이하도록 피난구 부근에 설치해야 한다"],["가스용기","분말소화약제의 가스용기는 분말소화약제의 저장용기에 접속하여 설치하여야 한다"],["가압용가스 용기","3병 이상 설치한 경우에는 2개 이상의 용기에 전자개방밸브를 부착하여야 한다"],["이산화탄소 양","가압용가스에 이산화탄소를 사용하는 것의 이산화탄소는 소화약제 1 kg에 대하여 20 g에 배관의 청소에 필요한 양을 가산한 양 이상으로 할 것"]]}],"11":[{"t":"tree","title":"감지기의 설치","root":"감지기","branches":[["전기자동차 충전구역","지하주차장에 한함 · 연기감지기는 아날로그 방식으로 한다"],["설치 위치","천장 또는 반자의 옥내에 면하는 부분에 설치할 것. 다만, 지하주차장에 설치하는 감지기의 경우에는 지하주차장의 보의 깊이가 30 cm 이상이고, 보와 보 사이의 내측면 간의 거리가 바닥으로부터 보가 설치된 천장까지의 수직 높이의 40% 이상인 때에는 보로 구획된 부분마다 1개 이상의 감지기를 설치해야 한다"],["정온식감지기","주방ㆍ보일러실 등으로서 다량의 화기를 취급하는 장소에 설치하되, 공칭작동온도가 최고주위온도보다 20℃ 이상 높은 것으로 설치해야 한다"],["설치 제외","파이프덕트 등 그 밖의 이와 비슷한 것으로서 2개층마다 방화구획된 것이나 수평단면적이 5 m^2 이하인 것은 감지기를 설치하지 아니한다"]]},{"t":"tree","title":"경계구역","root":"경계구역","branches":[["면적","하나의 경계구역의 면적은 600 m^2 이하로 하고 한변의 길이는 50 m 이하로 할 것"],["건축물","하나의 경계구역이 2개 이상의 건축물에 미치지 아니하도록 할 것"],["외기에 면한 부분","외기에 면하여 상시 개방된 부분이 있는 차고·주차장·창고 등에 있어서는 외기에 면하는 각 부분으로부터 5 m 미만의 범위 안에 있는 부분은 경계구역의 면적에 산입하지 않는다"]]},{"t":"table","title":"시각경보장치·수신기·절연저항","head":["항목","기준"],"rows":[["청각장애인용 시각경보장치","설치 높이는 천장의 높이가 2 m 이하인 경우에는 천장으로부터 0.15 m 이내의 장소에 설치해야 한다"],["수신기","화재로 인하여 하나의 층의 지구음향장치 또는 배선이 단락되어도 다른 층의 화재통보에 지장이 없도록 각 층 배선 상에 유효한 조치를 할 것"],["절연저항","감지기회로 및 부속회로의 전로와 대지 사이 및 배선 상호간의 절연저항은 1경계구역마다 직류 250 V의 절연저항측정기를 사용하여 측정한 절연저항이 0.1 ㏁ 이상이 되도록 할 것"]]}],"12":[{"t":"tree","title":"발신기","root":"발신기","branches":[["설치 장소","조작이 쉬운 장소에 설치하고, 조작스위치는 바닥으로부터 0.8 m 이상 1.5 m 이하의 높이에 설치해야 한다"],["수평거리","특정소방대상물의 층마다 설치하되, 해당 층의 각 부분으로부터 하나의 발신기까지의 수평거리가 25 m 이하가 되도록 설치해야 한다"],["위치표시등","발신기의 위치표시등은 함의 상부에 설치하되, 그 불빛은 부착 면으로부터 15° 이상의 범위 안에서 부착지점으로부터 10 m 이내의 어느 곳에서도 쉽게 식별할 수 있는 적색등으로 설치해야 한다"]]},{"t":"tree","title":"비상방송설비","root":"비상방송설비","branches":[["확성기 음성입력","3W(실내에 설치하는 것에 있어서는 1W) 이상일 것"],["확성기 설치","확성기는 각 층마다 설치하되, 그 층의 각 부분으로부터 하나의 확성기까지의 수평거리가 25 m 이하가 되도록 하고, 해당 층의 각 부분에 유효하게 경보를 발할 수 있도록 설치할 것"],["조작부","조작부의 조작스위치는 바닥으로부터 0.8 m 이상 1.5 m 이하의 높이에 설치할 것"],["음량조정기","음량조정기를 설치하는 경우 음량조정기의 배선은 3선식으로 할 것"],["창고시설","창고시설에서 발화한 때에는 전 층에 경보를 발해야 한다"]]},{"t":"tree","title":"단독경보형감지기","root":"단독경보형감지기","branches":[["설치 개수","각 실(이웃하는 실내의 바닥면적이 각각 30 m^2 미만이고 벽체의 상부의 전부 또는 일부가 개방되어 이웃하는 실내와 공기가 상호 유통되는 경우에는 이를 1개의 실로 본다)마다 설치하되, 바닥면적이 150 m^2를 초과하는 경우에는 150 m^2마다 1개 이상 설치할 것"],["건전지","건전지를 주전원으로 사용하는 단독경보형감지기는 정상적인 작동상태를 유지할 수 있도록 주기적으로 건전지를 교환할 것"],["2차전지","상용전원을 주전원으로 사용하는 단독경보형감지기의 2차전지는 「소방시설 설치 및 관리에 관한 법률」 제40조에 따라 제품검사에 합격한 것을 사용할 것"]]}],"13":[{"t":"tree","title":"피난기구의 설치","root":"피난기구","branches":[["착지점과 하강구","상호 수평거리 15센티미터 이상의 간격을 둘 것"],["승강식 피난기","승강식 피난기 및 하향식 피난구용 내림식사다리는 설치경로가 설치층에서 피난층까지 연계될 수 있는 구조로 설치할 것"],["하강구 내측","기구의 연결 금속구 등이 없어야 하며 전개된 피난기구는 하강구 수평투영면적 공간 내의 범위를 침범하지 않는 구조이어야 할 것"],["안정성","사용 시 기울거나 흔들리지 않도록 설치할 것"]]},{"t":"tree","title":"대피실과 피난유도선","root":"대피실·피난유도선","branches":[["피난유도선","축광방식의 피난유도선은 바닥으로부터 높이 50 cm 이하의 위치 또는 바닥 면에 설치할 것"],["비상조명등","대피실 내에는 비상조명등을 설치할 것"],["표지","대피실에는 층의 위치표시와 피난기구 사용설명서 및 주의사항 표지판을 부착할 것"]]}],"14":[{"t":"tree","title":"제연구역","root":"제연구역","branches":[["면적","하나의 제연구역의 면적은 1,000 m^2 이내로 할 것"],["통로","통로상의 제연구역은 보행중심선의 길이가 60 m를 초과하지 않을 것"],["거실과 통로","거실과 통로(복도를 포함한다)는 각각 제연구획 할 것"],["층","하나의 제연구역은 2개 이상 층에 미치지 아니하도록 할 것. 다만, 층의 구분이 불분명한 부분은 그 부분을 다른 부분과 별도로 제연구획 하여야 한다"]]},{"t":"tree","title":"풍도·전원","root":"제연설비","branches":[["수직풍도","내부면은 두께 0.5 mm 이상의 아연도금강판 또는 동등 이상의 내식성ㆍ내열성이 있는 것으로 마감하되, 접합부에 대하여는 통기성이 없도록 조치할 것"],["비상전원","제연설비를 유효하게 60분 이상 작동할 수 있도록 해야 한다"],["전원공급장치","화재에 노출이 우려되는 제연설비와 전원공급선 및 제트팬 사이의 전원공급장치 등은 250℃의 온도에서 60분 이상 운전상태를 유지할 수 있도록 할 것"],["대배기구","개폐용 전동모터는 정전 등 전원이 차단되는 경우에도 조작상태를 유지할 수 있도록 할 것"]]}],"15":[{"t":"tree","title":"비상콘센트설비","root":"비상콘센트설비","branches":[["회로","하나의 전용회로에 설치하는 비상콘센트는 10개 이하로 할 것"],["절연저항","전원부와 외함 사이를 500볼트 절연저항계로 측정할 때 20메가옴 이상일 것"],["비상전원","비상전원의 설치장소는 다른 장소와 방화구획 할 것"],["풀박스","비상콘센트용의 풀박스 등은 방청도장을 한 것으로서, 두께 1.6밀리미터 이상의 철판으로 할 것"]]},{"t":"tree","title":"무선통신보조설비","root":"무선통신보조설비","branches":[["설치 제외","지하층으로서 특정소방대상물의 바닥부분 2면 이상이 지표면과 동일한 경우에는 해당 층에 한해 설치하지 아니할 수 있다"],["분배기","분배기의 임피던스는 50 Ω의 것으로 할 것 · 분배기·분파기 및 혼합기 등의 임피던스는 50Ω의 것으로 할 것"],["증폭기","증폭기에는 비상전원이 부착된 것으로 하고 해당 비상전원 용량은 무선통신보조설비를 유효하게 30분 이상 작동시킬 수 있는 것으로 할 것"],["옥외안테나","수신기가 설치된 장소 등 사람이 상시 근무하는 장소에는 옥외안테나의 위치가 모두 표시된 옥외안테나 위치표시도를 비치할 것"]]},{"t":"table","title":"연결살수설비·지하구 연소방지설비","head":["설비","기준"],"rows":[["연결살수설비","헤드간의 수평거리는 개방형스프링클러헤드의 경우에는 1.5 m 이하로 할 것"],["지하구 연소방지설비 살수헤드","소방대원의 출입이 가능한 환기구ㆍ작업구마다 지하구의 양쪽방향으로 살수헤드를 설정하되, 한쪽 방향의 살수구역의 길이는 3 m 이상으로 할 것"],["지하구 연소방지설비 살수구역","환기구 사이의 간격이 700 m를 초과할 경우에는 700 m 이내마다 살수구역을 설정하되, 지하구의 구조를 고려하여 방화벽을 설치한 경우에는 그렇지 않다"]]}],"16":[{"t":"tree","title":"장비의 내진 기준","root":"내진설계","branches":[["제어반","제어반등의 하중이 450 N 이하이고 내력벽 또는 기둥에 설치하는 경우 직경 8 mm 이상의 고정용 볼트 4개 이상으로 고정할 수 있다"],["저장용기","지진하중에 의해 전도가 발생하지 않도록 설치할 것"],["기동장치·비상전원","지진으로 인한 오동작이 발생하지 않도록 설치하여야 한다"]]},{"t":"tree","title":"배관의 내진 기준","root":"배관의 내진설계","branches":[["건축 구조부재","흔들림 방지 버팀대가 부착된 건축 구조부재는 소화배관에 의해 추가된 지진하중을 견딜 수 있어야 한다"],["버팀대","흔들림 방지 버팀대의 세장비(L/r)는 300을 초과하지 않아야 한다 · 내력을 충분히 발휘할 수 있도록 견고하게 설치하여야 한다"],["상쇄배관","상쇄배관(offset)이란 영향구역 내의 직선배관이 방향전환 한 후 다시 같은 방향으로 연속될 경우, 중간에 방향전환 된 짧은 배관은 단부로 보지 않고 상쇄하여 직선으로 볼 수 있는 것을 말하며, 짧은 배관의 합산길이는 3.7 m 이하여야 한다"],["수평직선배관","하나의 수평직선배관은 최소 2개의 횡방향 흔들림 방지 버팀대와 1개의 종방향 흔들림 방지 버팀대를 설치하여야 한다 · 횡방향 흔들림 방지 버팀대의 간격은 중심선을 기준으로 최대간격이 12 m를 초과하지 않아야 한다"]]}]};
